&reftitle.changelog;





    &Version;
    &Description;





    8.5.0

     Passare l'intero 0 come argomento
     locales non è più supportato e
     ora lancia un TypeError.

  &reftitle.examples;



    Esempi di setlocale


<?php
/* Imposta la localizzazione in olandese */
setlocale(LC_ALL, 'nl_NL');

/* Visualizza: vrijdag 22 december 1978 */
echo strftime("%A %e %B %Y", mktime(0, 0, 0, 12, 22, 1978));

/* tenta i differenti nomi possibili per le impostazioni tedesche */
$loc_de = setlocale(LC_ALL, 'de_DE@euro', 'de_DE', 'de', 'ge');
echo "La localizzazione preferita per il tedesco su questo sistema è '$loc_de'";
?>







    Recuperare l'impostazione corrente con setlocale


<?php
/* Recupera l'impostazione corrente */
$current = setlocale(LC_ALL, null);

echo "Localizzazione corrente '$current'";
?>







    Esempi di setlocale per Windows


<?php
/* Imposta la localizzazione in olandese */
setlocale(LC_ALL, 'nld_nld');

/* Visualizza: vrijdag 22 december 1978 */
echo strftime("%A %d %B %Y", mktime(0, 0, 0, 12, 22, 1978));

/* tenta i differenti nomi possibili per le impostazioni tedesche */
$loc_de = setlocale(LC_ALL, 'de_DE@euro', 'de_DE', 'deu_deu');
echo "La localizzazione preferita per il tedesco su questo sistema è '$loc_de'";
?>
